"""Fail-closed review of a proposed posted-speed Native site packet.

This validates source provenance and engineering consistency before a capture.
It never decides legal applicability or asserts that a sign is physically seen.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


CASES = (
    "below", "above", "equal", "outside_zone", "opposite_direction",
    "non_authority_sign", "metric_equivalent", "sign_not_in_view",
)
SOURCE_FIELDS = (
    "highway_dedication_source", "public_access_source",
    "narrow_road_geometry_source", "vehicle_clearance_source",
    "governed_segment_source", "governed_direction_source",
    "sign_position_source", "posting_authority_source",
)


def load(path: Path, expected_sha256: str, case_id: str) -> dict:
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("reviewed posted-speed site hash mismatch")
    packet = json.loads(raw)
    if packet.get("case_id") != case_id or packet.get("source_kind") != "reviewed_original_site":
        raise ValueError("reviewed original site identity missing")
    if not all(isinstance(packet.get(key), str) and packet[key] for key in SOURCE_FIELDS):
        raise ValueError("posted-speed site provenance incomplete")
    for key in ("governed_road_id", "governed_segment_id", "governed_direction",
                "vehicle_id", "sign_id", "sign_jurisdiction", "sign_installation_record"):
        if not isinstance(packet.get(key), str) or not packet[key]:
            raise ValueError("posted-speed site identity incomplete: " + key)
    if packet.get("unit") not in ("mph", "km/h", "m/s") or type(packet.get("rate")) not in (int, float) or packet["rate"] <= 0:
        raise ValueError("posted-speed rate or unit invalid")
    if type(packet.get("public_authority_posted")) is not bool:
        raise ValueError("public-authority status missing")
    if type(packet.get("sign_in_camera_view")) is not bool:
        raise ValueError("sign visibility remains unreviewed")
    if not packet["sign_in_camera_view"] and not packet.get("off_camera_reading_assumption_source"):
        raise ValueError("off-camera governing limit remains unknown without reading assumption")
    lanes = packet.get("travel_lanes")
    if not isinstance(lanes, dict) or not all(isinstance(lanes.get(direction), str) and lanes[direction] for direction in ("forward", "opposite")):
        raise ValueError("both actual travel directions need reviewed lane identities")
    if lanes["forward"] == lanes["opposite"]:
        raise ValueError("opposite travel requires a distinct reviewed lane")
    return packet

"""Engineering speed requests, never legal speed tolerance or outcome labels."""
from __future__ import annotations

import math


UNIT = {"mph": 0.44704, "km/h": 5 / 18, "m/s": 1.0}


def target_speed(site: dict, variables: dict) -> float:
    if site.get("unit") not in UNIT or type(site.get("rate")) not in (int, float):
        raise ValueError("reviewed posted rate and unit required")
    posted = site["rate"] * UNIT[site["unit"]]
    relation = variables["rate_relation"]
    if relation not in ("below", "equal", "above"):
        raise ValueError("unknown requested speed relation")
    # One m/s is an engineering separation for construction trials, not a legal
    # threshold or a claim that actual speed realizes the requested relation.
    target = posted + {"below": -1.0, "equal": 0.0, "above": 1.0}[relation]
    if not math.isfinite(target) or target < 0:
        raise ValueError("requested engineering target invalid")
    return target


def command(actual_mps: float, target_mps: float, gain: float) -> tuple[float, float]:
    if any(type(value) not in (int, float) or not math.isfinite(value)
           for value in (actual_mps, target_mps, gain)) or min(actual_mps, target_mps) < 0 or gain <= 0:
        raise ValueError("invalid measured speed or controller gain")
    error = (target_mps - actual_mps) * gain
    return min(max(error, 0.0), 1.0), min(max(-error, 0.0), 1.0)

"""Independent pre-acceptance audit for an original posted-speed attempt.

The pinned media decoder and local acceptance still run separately. This stage
rejects missing original source and stale camera/trace references; it does not
turn accepted metadata or diagnostic fixture data into physical evidence.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from speed_source_review import ASSIGNMENT, measure


MEDIA = ("overview", "approach", "reference_corner", "driver_reference")


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def audit(attempt: Path, inventory: dict, case_id: str) -> dict:
    attempt = Path(attempt).resolve()
    if case_id != inventory.get("case_id") or not case_id.startswith(ASSIGNMENT + "__"):
        raise ValueError("original delivery exact case mismatch")
    if inventory.get("diagnostic_fixture") is True:
        raise ValueError("diagnostic fixture cannot supply original delivery")
    result = measure(attempt, inventory, case_id)
    if inventory.get("source_kind") != "original_native":
        raise ValueError("original Native acquisition required")
    media = inventory.get("media")
    if not isinstance(media, dict) or set(media) != set(MEDIA) | {"trace"}:
        raise ValueError("complete four-view original media and trace inventory required")
    hashes = {}
    for name, entry in media.items():
        path = Path(entry.get("path", ""))
        if path.is_absolute() or ".." in path.parts:
            raise ValueError("original media path escapes attempt")
        target = (attempt / path).resolve()
        if not target.is_relative_to(attempt) or not target.is_file():
            raise ValueError("original media source missing: " + name)
        if target.stat().st_size == 0 or sha(target) != entry.get("sha256"):
            raise ValueError("original media source empty or stale: " + name)
        hashes[name] = entry["sha256"]
    if not all(media[name]["path"].endswith(".mkv") for name in MEDIA):
        raise ValueError("four original camera videos must be retained")
    if not media["trace"]["path"].endswith(".jsonl"):
        raise ValueError("original trace source must be retained")
    return {"format": "c136559-original-source-audit-v1", "case_id": case_id,
            "original_frames": result["original_frames"],
            "source_sha256": result["source_sha256"], "media_sha256": hashes,
            "governed_frames": result["governed_frames"],
            "observed_above_frames": result["observed_above_frames"],
            "physical_completion_confirmed": False,
            "full_video_decode_confirmed": False,
            "legal_applicability": "unresolved"}


def main() -> None:
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise ValueError("refusing to overwrite prior original source audit")
    inventory = json.loads((args.attempt / "inventory.json").read_text())
    result = audit(args.attempt, inventory, args.case)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")


if __name__ == "__main__":
    main()
